#!/usr/bin/env node
// Generates Claude Code native slash-command files from this repo's SKILL.md frontmatter.
// This is the mechanism that actually makes `/kbd-analyze` (or any other ported skill) show up
// as a typeable command -- independent of, and in addition to, the plugin/marketplace listing
// generated by generate-skill-system-distribution.mjs. Ported from
// prometheus-skill-pack/scripts/generate-commands.js.
//
// Usage:
//   node scripts/generate-commands.mjs [--output <dir>] [--uninstall]
// Default output: ~/.claude/commands (matching the full pack's own default). Always overridable
// via --output so tests never touch a real home directory.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { homeDir } from '../lib/platform/paths.mjs';
import { atomicWrite } from '../lib/platform/atomic-write.mjs';
import { parseSkillFrontmatter } from '../lib/distribution/frontmatter.mjs';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SKILLS_DIR = path.join(REPO_ROOT, 'skills');

function findSkillMds(dir, results = []) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) findSkillMds(fullPath, results);
    else if (entry.name === 'SKILL.md') results.push(fullPath);
  }
  return results;
}

function parseArgs(argv) {
  const outputIndex = argv.indexOf('--output');
  const outputDir =
    outputIndex !== -1 ? path.resolve(argv[outputIndex + 1]) : path.join(homeDir(), '.claude', 'commands');
  return { outputDir, uninstall: argv.includes('--uninstall') };
}

function commandContent(skillMdPath, description) {
  // Absolute path, and instruct the agent to read it -- {{file:}} is not expanded by Claude Code
  // (it is OpenCode-specific), so a relative path resolving against ~/.claude/commands/ would
  // point at the wrong root entirely. Same fix the full pack's generator carries, for the same
  // reason: a literal unexpanded token used to be the whole prompt body.
  const absolutePath = skillMdPath.replace(/\\/g, '/');
  const escapedDescription = description
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 200)
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"');
  return (
    `---\ndescription: "${escapedDescription}"\n---\n\n` +
    `<!-- generated by prometheus-skills-mini: scripts/generate-commands.mjs -->\n\n` +
    `Read \`${absolutePath}\` in full, then follow its instructions to execute this skill.\n\n` +
    `$ARGUMENTS\n`
  );
}

function run({ outputDir, uninstall }) {
  const skillMds = findSkillMds(SKILLS_DIR);
  let count = 0;
  let skipped = 0;

  if (uninstall) {
    for (const skillMdPath of skillMds) {
      const { name } = parseSkillFrontmatter(skillMdPath);
      if (!name) {
        skipped += 1;
        continue;
      }
      try {
        fs.unlinkSync(path.join(outputDir, `${name}.md`));
        count += 1;
      } catch {
        /* already gone */
      }
    }
    console.log(`Removed ${count} command file(s) from ${outputDir} (skipped ${skipped})`);
    return;
  }

  fs.mkdirSync(outputDir, { recursive: true });
  for (const skillMdPath of skillMds) {
    const { name, description } = parseSkillFrontmatter(skillMdPath);
    if (!name || !description) {
      skipped += 1;
      continue;
    }
    atomicWrite(path.join(outputDir, `${name}.md`), commandContent(skillMdPath, description));
    count += 1;
  }
  console.log(`Generated ${count} command file(s) -> ${outputDir} (skipped ${skipped})`);
}

run(parseArgs(process.argv.slice(2)));
